    List<PersonAlias> findByPersonId(Long personId);

    boolean existsBySheetIdAndAliasKey(String sheetId, String aliasKey);

    Optional<PersonAlias> findBySheetIdAndAliasKey(String sheetId, String aliasKey);
}
